import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山澤損","description":"周易折中 - 山澤損","frontmatter":{"title":"山澤損","description":"周易折中 - 山澤損"},"headers":[],"relativePath":"classics/zhezhong/047.md","filePath":"classics/zhezhong/047.md"}'),h={name:"classics/zhezhong/047.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山澤損" tabindex="-1">山澤損 <a class="header-anchor" href="#山澤損" aria-label="Permalink to “山澤損”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈損序卦〉解曰：“緩也。緩必有所失，故受之以損。縱緩則必有所失，失則損也。損所以繼解也。為卦艮上兌下，山體高，澤體深，下深則上益高，為損。下益上之義也。又澤在山下，其氣上通，潤及草木百物，是損下而益上也。又下為兌說，三爻皆上應，是說以奉上，亦損下益上之義也。又下兌之成兌，由六三之變也，上艮之成艮，自上九之變也。三本剛而成柔，上本柔而成剛，亦損下益上之義。損上而益於下，則為益；取下而益於上，則為損。在人上者，施其澤以及下，則益也；取其下以自厚，則損也。譬諸壘土，損於上以培厚其基本，則上下安固矣，豈非益乎？取於下以増上之高，則危墜至矣，豈非損乎？故損者，損下益上之義；益則及是。”</p><p>損：有孚，元吉，無咎，可貞，利有攸往 【1】 ，曷之用，二簋可用享 【2】</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>【1】損，減省也。為卦損下卦上畫之陽，益上卦上畫之陰，損兌澤之深，益艮山之高，損下益上，損內益外，剝民奉君之象，所以為損也。損所當損而有孚信，則其佔當有此下四者之應矣。</p><p>【2】言當損時則至薄無害。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>【1】損，減損也。凡損抑其過以就義理，皆損之道也。損之道必有孚誠，謂至誠順於理也。損而順理，則大善而吉，所損無過差，可貞固常行，而利有所往也。人之所損或過或不及或不常，皆不合正理，非有孚也。非有孚則無吉而有咎，非可貞之道，不可行也。</p><p>【2】損者，損過而就中，損浮末而就本實也。聖人以寧儉為禮之本，故為損發明其義，以享祀言之。享祀之禮，其文最繁，然以誠敬為本。多儀備物所以將飾其誠敬之心，飾過其誠則為偽矣。損飾所以存誠也，故云“曷之用二簋，可用享”。二簋之約，可用享祭，言在乎誠而已。誠為本也。天下之害，無不由末之勝也。峻宇雕牆本於宮室，酒池肉林本於飲食，淫酷殘忍本於刑罰，窮兵黷武本於徵討。凡人慾之過者，皆本於奉養。其流之遠，則為害矣。先王制其本者，天理也；後人流於末者，人慾也。損之義，損人慾以復天理而已。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>呂氏大臨曰 ：損之道不可以為正當損之時，故曰可貞。時損則損，時益則益。苟當其時，無往而不可，故損益皆利有攸往。</p></li><li><p>蔡氏清曰 ：剝民奉君之義，只可用之卦名。其卦辭“有孚，元吉，無咎，可貞，利有攸往”，只承“損”字泛說，言損所當損，人人皆可用，不專指上之損下也。益卦“利有攸往，利涉大川”亦然，豈專為益下之事乎？</p></li><li><p>孔氏穎達曰 ：“曷之用二簋，可用享”者，明行損之禮貴夫誠信，不在於豐。二簋至約，可用享祭。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>彖辭自“有孚”以下泛說損所當損之義，蔡氏之說極為得之。蓋損益者時也，時在當損，不得不損，惟以誠意為主而行之，又得乎大善之吉，則不但無咎，而且可以為常道而利有所往矣。舉一端以明之，則如二簋薄祭，固因乎時而節損者也。然能積誠盡禮，則可以致孝乎鬼神，而推之凡事之當損者，視此矣。卦義以孚而行損，程傳則因損以致孚，略有不同也。</p><p>象曰：山下有澤，損；君子以懲忿窒欲</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>君子修身所當損者，莫切於此。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>山下有澤，氣通上潤，與深下以增高，皆損下之象。君子觀損之象，以損於己。在修身之道所當損者，唯忿與欲。故以懲戒其忿怒，窒塞其意欲也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰：兌說，故懲忿；艮止，故窒慾。</p></li><li><p>孔氏穎達曰：懲者，息其既往；窒者，閉其將來。懲窒互文而相足也。</p></li><li><p>楊氏時曰：損德之修也，所當損者惟忿欲而已。故九思始於視聽貌言，終於忿思難見，得思義者以此。</p></li><li><p>朱子語類 問：何以窒慾？伊川雲：思此莫是欲心一萌，當思禮義以勝之。否曰：然。</p></li><li><p>王氏申子曰：和說則無忿，知止則無慾。故曰脩德之要也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>凡大象配兩體之德者，皆先內後外，故當以虞氏之說為是。益象亦然。</p><p>彖曰：損，損下益上，其道上行</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>損之所以為損者，以損於下而益於上也。取下以益上，故云其道上行。夫損上而益下則為益，損下而益上則為損。損基本以為高者，豈可謂之益乎？</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蔡氏清曰 ：損下益上，利歸於上也，故曰其道上行。下損則上不能獨益矣，卦所以為損也。</p></li><li><p>林氏希元曰 ：損下益上，下損則上亦損，故曰其道上行。道者，損之道也。程傳小注、蒙引俱作利歸於上說，愚謂卦以損下取名，所重不在於利，又難以道為利。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>蔡氏、林氏兩說沿襲用之，今思之於卦義皆未全。蓋說者但主取民財一事耳，豈知如人臣之致身事主，百姓之服役奉公，皆損下益上之事也。必如此，然後上下交而志同，豈非其道上行乎？上行與“地道卑而上行”之義同，下能益上則道上行矣，上能益下則道大光矣。如此，則“道”字方有意味，而於兩卦諸爻之義亦合。</p><p>損而有孚，元吉，元咎，可貞，利有攸往，曷之用？二簋可用享。二簋應有時，損剛益柔，有時損益盈虛，與時偕行</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>此釋卦辭，時謂當損之時。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>謂損而以至誠，則有此兀吉以下四者，損道之盡善也。夫子特釋“曷之用？二簋可用享”卦辭，簡直謂當損去浮飾，曰何所用哉？二簋可以享也。厚本損末之謂也。夫子恐後人不逹，遂以為文飾當盡去，故詳言之。有本必有末，有實必有文。天下萬事無不然者，無本不立，無文不行。父子主恩，必有嚴順之體；君臣主敬，必有承接之儀。禮讓存乎內，待威儀而後行；尊卑有其序，非物採則無別。文之與實，相須而不可缺也。及夫文之勝，末之流逺，本喪實，乃當損之時也。故云“曷所用哉？二簋足以薦其誠矣”，謂當務實而損飾也。夫子恐人之泥言也，故復明之曰“二簋之質，用之當有時”，非其所用而用之不可也。謂文飾未過而損之，與損之至於過甚，則非也。損剛益柔有時，剛為過，柔為不足。損益皆損剛益柔也，必順時而行。不當時而損益之，則非也。或損或益，或盈或虛，唯隨時而已。過者損之，不足者益之，虧者盈之，實者虛之，與時偕行也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>徐氏幾曰 ：卦辭曰“損有孚”，彖傳曰“損而有孚”，加以“而”字，義曉然矣。</p></li><li><p>張氏清子曰 ：當其可之謂時，當損而損時也，不當損而損則非時。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>程傳之義施於賁卦則可，此卦所謂損者，乃謂時當節損，如家則稱貧富之有無，國則視兇豐為豐儉之類耳。故曰“損而有孚”，言時雖不得已而損，而以有孚行之，如祭祀雖不能備品，而以至誠將之也。二簋喻節損之義，然下雲“損剛益柔”者，非以損剛喻二簋也。剛為本，喻孚誠；柔為末，喻儀物。以孚誠之有餘，補儀物之不足，則雖二簋而不嫌於簡矣，此損剛益柔之義。</p><p>初九：已事遄往，無咎，酌損之</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>初九當損下益上之時，上應六四之陰，輟所為之事而速往以益之，無咎之道也。故其象佔如此，然居下而益上，亦當斟酌其淺深也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>損之義，損剛益柔，損下益上也。初以陽剛應於四，四以陰柔居上位，賴初之益者也。下之益上，當損己而不自以為功，所益於上者事既已，則速去之，不居其功，乃無咎也。若享其成功之美，非損己益上也，於為下之道為有咎矣。四之陰柔賴初者也，故聽於初。初當酌度其宜而損己以益之，過與不及皆不可也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎逹曰 ：損之為道，損下益上，如人臣欲自損己奉上。然各有職掌，若廢事而往，咎莫大焉。竟事速往，乃得無咎。酌損之者，以剛奉柔，初未見親也，故須酌而減損之。</li></ul><p>孔氏穎逹曰 ：損之為道，損下益上，如人臣欲自損己奉上。然各有職掌，若廢事而往，咎莫大焉。竟事速往，乃得無咎。酌損之者，以剛奉柔，初未見親也，故須酌而減損之。</p><ul><li>朱子語類雲 ：酌損之在損之初，下猶可以斟酌也。</li></ul><p>朱子語類雲 ：酌損之在損之初，下猶可以斟酌也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>孔氏說“已事”之義，謂如學優而後從政之類，於理亦精。</p><p>象曰：已事遄往，尚合志也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>尚，上通。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>尚，上也。時之所崇用為尚。初之所尚者，與上合志也。四賴於初，初益於四，與上合志也。</p><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>易例初九與六四雖正應，卻無往從之義。在下位不援上也。惟損初爻言遄往，而傳謂上合志，蓋當損下益上之時故也。</p><p>九二：利貞，徵兇，弗損益之</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>九二剛中，志在自守，不肯妄進，故佔者利貞而徵則兇也。弗損益之言，不變其所守，乃所以益上也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二以剛中當損剛之時，居柔而說體，上應六五陰柔之君。以柔說應上，則失其剛中之德，故戒所利在貞正也。徵，行也。離乎中則失其貞正而兇矣。守其中乃貞也，弗損益之，不自損其剛貞，則能益其上，乃益之也。若失其剛貞而用柔說，適足以損之而已，非損己而益上也。世之愚者，雖無邪心而唯知竭力順上為忠者，蓋不知弗損益之之義也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>林氏希元曰 ：九二在爻則為剛中，在人事則為志在自守，不肯妄進。志在自守，不肯妄進，九二之貞也。故佔者利於守貞，若徵行，則是變其所守而得兇矣。夫自守而不妄進，宜若無益於上矣，然由是而啟時君尊德樂道之心，止士大夫奔競之習，其益於上也不少。是弗損乃所以益之也。桐江一絲系漢九鼎，清風高節披拂士習，可當此爻之義。</li></ul><p>象曰：九二利貞，中以為志也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>九居二，非正也；處說非剛也。而得中為善，若守其中，德何有不善？豈有中而不正者？豈有中而有過者？二所謂利貞，謂以中為志也。志存乎中，則自正矣。大率中重於正，中則正矣，正不必中也。能守中則有益於上矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：言九二所以能居而守貞，不損益之良由，居中以中為志，故損益得其節適也。</p></li><li><p>王氏宗傳曰：順從為事，則在己者所損多矣。以道自守，乃所以益之，故曰九二利貞，中以為志也。中以為志，則在己者無失，而益上之實亦無出諸此。</p></li></ul><p>六三：三人行則損一人，一人行則得其友</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>下卦本幹而損上爻以益坤，三人行而損一人也；一陽上而一陰下，一人行而得其友也。兩相與則專，三則雜而亂，卦有此象，故戒佔者當致一也。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>損者，損有餘也；益者，益不足也。三人謂下三陽上三陰。三陽同行，則損九三以益上三陰；同行，則損上六以為三。三人行則損一人也。上以柔易剛而謂之損，但言其減一耳。上與三雖本相應，由二爻升降而一卦皆成兩相與也。初二二陽，四五二陰，同德相比，三與上應皆兩相與，則其志專，皆為得其友也。三雖與四相比，然異體而應上，非同行者也。三人則損一人，一人則得其友。蓋天下無不二者，一與二相對待，生生之本也。三則餘而當損矣。此損益之大義也。夫子又於繫辭盡其義曰：“天地絪縕，萬物化醇；男女構精，萬物化生。《易》曰：‘三人行則損一人，一人行則得其友’，言致一也。”絪縕交密之狀，天地之氣相交而密，則生萬物之化醇。醇謂醲厚，醲厚猶精一也。男女精氣交構，則化生萬物。惟精醇專一，所以能生也。一陰一陽豈可二也？故三則當損，吉專致乎一也。天地之間，當損益之明且大者，莫過此也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>林氏希元曰 ：此爻之辭兼舉六爻，以三正是當損之爻，乃卦之所以為損者，故於此言之。</li></ul><p>林氏希元曰 ：此爻之辭兼舉六爻，以三正是當損之爻，乃卦之所以為損者，故於此言之。</p><ul><li>楊氏啟新曰 ：人之相與，惟其心之同而已。苟精神不孚，意氣不貫，則群黨比周，固三也；即一人之異，亦三也，是皆不可以不損也。苟精神相孚，意氣相貫，則二人同心，固兩也；即千百其朋，亦兩也，是皆不可以不得者也。</li></ul><p>楊氏啟新曰 ：人之相與，惟其心之同而已。苟精神不孚，意氣不貫，則群黨比周，固三也；即一人之異，亦三也，是皆不可以不損也。苟精神相孚，意氣相貫，則二人同心，固兩也；即千百其朋，亦兩也，是皆不可以不得者也。</p><p>象曰：一人行三則疑也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>一人行而得一人，乃得友也。若三人行，則疑所與矣。理當損去其一人，損其餘也。案自二以上，皆可以三概之，不必正三人也。季文子三思，南容三複之類。</p><p>六四：捐其疾，使遄有喜，無咎</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以初九之陽剛益已而損其陰柔之疾，唯速則善，戒佔者如是則無咎也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四以陰柔居上，與初之剛陽相應，在損時而應剛，能自損以從剛陽也，損不善以從善也。初之益四，損其柔而益之以剛，其不善損也。故曰“損其疾”，疾謂疾病，不善也。損於不善，唯使之遄速，則有喜而無咎。人之損過，唯患不速，速則不致於深過，為可喜也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：履得其位，以柔納剛，能損其疾也。疾何可久？故速乃有喜，有喜乃無咎也。</li></ul><p>王氏弼曰 ：履得其位，以柔納剛，能損其疾也。疾何可久？故速乃有喜，有喜乃無咎也。</p><ul><li>蘇氏軾曰 ：遄者，初九也。損其疾，則初之從我也易，故遄有喜。</li></ul><p>蘇氏軾曰 ：遄者，初九也。損其疾，則初之從我也易，故遄有喜。</p><ul><li>楊氏萬里曰 ：六四以柔居柔，得初九之陽以為應，損其疾者也。初言“遄往”，四言“使遄”，蓋初之遄實四有以使之也。</li></ul><p>楊氏萬里曰 ：六四以柔居柔，得初九之陽以為應，損其疾者也。初言“遄往”，四言“使遄”，蓋初之遄實四有以使之也。</p><ul><li>胡氏炳文曰 ：六四與初九為應，初方巳其事而速於益四，四損其陰柔之疾，惟速則有喜，不然彼方汲汲，此乃悠悠，非受益之道。又曰：下損已以益上，當使下亦速，所喜乃無咎。</li></ul><p>胡氏炳文曰 ：六四與初九為應，初方巳其事而速於益四，四損其陰柔之疾，惟速則有喜，不然彼方汲汲，此乃悠悠，非受益之道。又曰：下損已以益上，當使下亦速，所喜乃無咎。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>蘇氏、楊氏說於“使”字語氣亦近是。</p><p>象曰：損其疾亦可喜也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>損其所疾，固可喜也。“亦”發語辭。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰：能不吝其疾，自損以受之，使合志者得效其忠，豈非可喜之事哉。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>易多言有喜，而此傳雲“亦可喜也”，則此喜不主己身，乃主於使遄來而益我者有喜。故變文曰“可喜者”，他人之辭也。</p><p>六五：或益之十朋之龜，弗克違，元吉</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>柔順虛中以居尊位，當損之時，受天下之益者也。兩龜為朋，十朋之龜，大寶也。或以此益之，而不能辭，其吉可知。佔者有是德，則獲其應也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五於損時，以中順居尊位，虛其中以應乎二之剛陽，是人君能虛中自損以順從在下之賢也。能如是，天下孰不損己自盡以益之？故或有益之之事，則十朋助之矣。十朋，眾辭。龜者，決是非吉凶之物，眾人之公論必合正理，雖龜筴不能違也。如此，可謂大善之吉矣。古人曰：“謀從眾則合天心。”</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>張子曰 ：龜弗能違，言受益之可必，信然不疑也。</li></ul><p>張子曰 ：龜弗能違，言受益之可必，信然不疑也。</p><ul><li>楊氏時曰 ：柔得尊位，虛己而下人，則謙受益時乃天道。天且不違，況於人乎？況於鬼神乎？宜其益之者至矣。故曰“或益之十朋之龜，弗克違，元吉”。</li></ul><p>楊氏時曰 ：柔得尊位，虛己而下人，則謙受益時乃天道。天且不違，況於人乎？況於鬼神乎？宜其益之者至矣。故曰“或益之十朋之龜，弗克違，元吉”。</p><ul><li>郭氏雍曰 ：益之至，豈獨人事而已，雖元龜之靈弗能違，此其所以元吉也。《洪範》曰：“汝則從龜從筮，從卿士，從庶民。”從是之謂大同。六五之元吉，猶《洪範》之大同也。</li></ul><p>郭氏雍曰 ：益之至，豈獨人事而已，雖元龜之靈弗能違，此其所以元吉也。《洪範》曰：“汝則從龜從筮，從卿士，從庶民。”從是之謂大同。六五之元吉，猶《洪範》之大同也。</p><ul><li>楊氏時曰 ：“或者”不一之辭，益之者不一也，人心歸之也。十朋之龜皆從而弗違，天與鬼神祐之也。鬼神祐之，故龜筮協從。</li></ul><p>楊氏時曰 ：“或者”不一之辭，益之者不一也，人心歸之也。十朋之龜皆從而弗違，天與鬼神祐之也。鬼神祐之，故龜筮協從。</p><p>象曰：六五元吉，自上祐也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>所以得元吉者，以其能盡眾人之見，合天地之理，故自上天降之福祐也。</p><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>自上祐以為正釋，龜筮弗違亦可。然觀益二言“朋龜不違”，下又云“享於帝吉”，則帝者又百神之主也。故此上祐，亦是言天心克享，人神不能違也。</p><p>上九：弗損益之，無咎，貞吉，利有攸往，得臣無家</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>上九當損下益上之時，居卦之上，受益之極而欲自損以益人也。然居上而益下，有所謂“惠而不費”者，不待損己然後可以益人也。能如是，則無咎。然亦必以正則吉，而利有所往。惠而不費，其惠廣矣，故又曰“得臣無家”。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>凡損之義有三：損己從人也，自損以益於人也，行損道以損於人也。損己從人，徙於義也；自損益人，及於物也；行損道以損於人，行其義也。各因其時取大者言之。四五二爻取“損己從人”，下體三爻取“自損以益人”，損時之用；行損道以損天下之當損者也。上九則取“不行其損”為義。九居損之終，損極而當變者也。以剛陽居上，若用剛以損削於下，非為上之道，其咎大矣。若不行其損變，而以剛陽之道益於下，則無咎而得其正且吉也。如是，則宜有所往，往則有益矣。在上能不損其下而益之，天下孰不服從？從服之眾無有內外也，故曰“得臣無家”。得臣，謂得人心歸服；無家，謂無有遠近內外之限也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏肅曰 ：處損之極，損極則益，故曰“不損益之”。得臣，則萬方一軌，故無家也。</li></ul><p>王氏肅曰 ：處損之極，損極則益，故曰“不損益之”。得臣，則萬方一軌，故無家也。</p><ul><li>句氏微曰 ：上九剛德為物所歸，雖曰得臣，非已所有，蓋以四海為家。</li></ul><p>句氏微曰 ：上九剛德為物所歸，雖曰得臣，非已所有，蓋以四海為家。</p><ul><li>朱子語類雲 ：得臣有家，其所得也小矣；無家則可見其大。</li></ul><p>朱子語類雲 ：得臣有家，其所得也小矣；無家則可見其大。</p><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>卦以損三益上成義，則上者受益之極，卦之主也。故“無咎”、“可貞”、“利有攸往”之辭，皆與卦同。其不言“有孚元吉”者，弗損於下而有益於己，此非有至誠仁愛之心者不能也。蓋黎民之生厚，則所以固本寜邦者至矣；仁義之俗成，則其有遺親後君者鮮矣。其為益孰大於是？然其不損於下者，乃所以自損於己也。此所以合乎卦義，有孚元善之德也。得臣無家，則又極言弗損之規模與夫獲益之氣象。自其弗損之心而言之，為天下君而不自利於己；自其得益之量而言之，莫匪王臣而不視為私屬，皆所謂“得臣無家”，王道之至也。蓋五上二爻相蒙為義，五之虛中既已格乎鬼神而元吉，則彖所謂“有孚元吉”者巳備，故於此爻遂究其說以終其義也。九二之“弗損”謂損己益之謂益人，此爻之“弗損”謂損人益之謂益己，辭同而指異者，卦義損下益上，故在下卦為自損，在上卦為受益。卦名以損下益上為義，卦辭則泛論損所當損而損中有益也。六爻之辭，其以上下體分損益，則根乎卦名；其言損所當損而損中有益，則又根乎卦辭。</p><p>象曰：弗損益之大得志也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>居上不損下而反益之，是君子大得行其志也。君子之志，唯在益於人而已。</p>',144)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
